sub new {
    my ($class, $name) = @_;
    my $self = { name => $name };
    return bless $self, $class;
}

sub speak {
    my $self = shift;
    return $self->SUPER::speak() . "... Woof!";
}

sub speak {
    my $self = shift;
    return "The " . $self->{name} . " makes a sound";
}

sub area {
    die "Subclass must implement area";
}

sub new {
    my ($class, %args) = @_;
    my $self = {
        greeting => $args{greeting} || "Hello",
    };
    return bless $self, $class;
}
